<script>
(function(){
  var imgs = document.querySelectorAll('.prd_img');
  var contents = document.querySelectorAll('.content_slide');
  var dots = document.querySelectorAll('.dot');
  var total = imgs.length;
  var current = 0;

  function showSlide(idx){
    if (idx < 0) idx = total - 1;
    if (idx >= total) idx = 0;
    current = idx;
    imgs.forEach(function(el, i){ el.style.display = (i === idx) ? 'block' : 'none'; });
    contents.forEach(function(el, i){ el.style.display = (i === idx) ? 'block' : 'none'; });
    dots.forEach(function(el, i){ el.classList.toggle('active', i === idx); });
  }

  window.plusSlide = function(n){ showSlide(current + n); };
  window.goToSlide = function(idx){ showSlide(idx); };

  window.openProduct = function(){
    var prdId = imgs[current].getAttribute('data-prd-id');
    var url = "https://www.saramin.co.kr/zf_user/store/product?salePrdCd=" + prdId + "&t_ref=br_inapp_p_newintern_req_01";
    try {
      appboyBridge.openLink(url);
    } catch(e) {
      window.open(url, "_blank");
    }
  };

  var heroEl = document.querySelector('.hero');
  var startX = 0;
  var dragging = false;
  heroEl.addEventListener('pointerdown', function(e){ startX = e.clientX; dragging = true; });
  heroEl.addEventListener('pointerup', function(e){
    if (!dragging) return;
    dragging = false;
    var diff = e.clientX - startX;
    if (Math.abs(diff) > 40) { plusSlide(diff > 0 ? -1 : 1); }
  });
  heroEl.addEventListener('pointercancel', function(){ dragging = false; });

  showSlide(0);
})();
</script>

